/bin/bash -lc "head -114 /tmp/SwapSyntax.v >/tmp/SwapSyntaxProbe.v
cat >>/tmp/SwapSyntaxProbe.v <<'EOF'
  apply trm_mutind; intros;
    cbn [transform_trm transform_lit transform_def transform_defs];
    try reflexivity; f_equal;
    try solve [unfold avar_map; apply rename_avar_fixed; fixed_fv];
    try solve [match goal with
    | IH : forall d, preserves_fv _ _ -> _ |- _ =>
        apply IH; fixed_fv
    end].
  Show.
EOF
rocq top -quiet -w -all -R rodot roDOT -R .rocq-deps/TLC TLC </tmp/SwapSyntaxProbe.v 2>&1 | tail -120"

