/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
p=Path('/tmp/TaskNarrow.v')
s=p.read_text()
s=s.replace('''    cbn [ctx_obj_met] in *; rewrite Hvis;
    apply ctx_typing_morphism_push;
    [apply ctx_typing_morphism_push;
      [try apply ctx_typing_morphism_hide; exact HMself |]
    |];
    cbn [ctx_dom objctx_dom] in *;
    rewrite ?union_empty_l, ?notin_union, ?notin_singleton in *; tauto.''','''    cbn [ctx_obj_met] in *; rewrite Hvis.
  all: apply ctx_typing_morphism_push; [| idtac].
  all: try solve [cbn [ctx_dom objctx_dom] in *;
    rewrite ?union_empty_l, ?notin_union, ?notin_singleton in *; tauto].
  all: apply ctx_typing_morphism_push; [try apply ctx_typing_morphism_hide; exact HMself |].
  all: cbn [ctx_dom objctx_dom] in *;
    rewrite ?union_empty_l, ?notin_union, ?notin_singleton in *; tauto.''')
p.write_text(s)
PY
timeout 45s rocq c -time -w -all -R rodot roDOT -R .rocq-deps/TLC TLC /tmp/TaskNarrow.v > /tmp/rodot-narrow-terms3.log 2>&1
tail -23 /tmp/rodot-narrow-terms3.log"

